<script setup lang="ts">
import {ref,onMounted,watch,onBeforeUnmount} from 'vue';
import {apiError} from './apiError';
import SeriesPreview from './SeriesPreview.vue';
defineProps<{disabled:boolean}>();const emit=defineEmits<{apply:[csv:string,source:any]}>();
const catalog=ref<any>();const selected=ref('alashankou-2023');const start=ref(0);const hours=ref(8760);const preview=ref<any>();const error=ref('');const loading=ref(false);let request=0;
watch([selected,start,hours],()=>{preview.value=null;++request;loading.value=false});
onBeforeUnmount(()=>++request);
onMounted(async()=>{try{const r=await fetch('/api/input-datasets');if(!r.ok)throw Error('历史数据目录读取失败');catalog.value=await r.json()}catch(e){error.value=String(e)}});
async function inspect(){const id=++request;loading.value=true;preview.value=null;error.value='';try{const r=await fetch(`/api/input-datasets/${selected.value}/preview?start=${start.value}&hours=${hours.value}`);const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));if(id===request)preview.value=d}catch(e){if(id===request)error.value=String(e)}finally{if(id===request)loading.value=false}}
function apply(){if(preview.value)emit('apply',preview.value.csv,{...preview.value.source_import,network:preview.value.network,network_parameters:preview.value.network_parameters,branch_limit_kw:preview.value.branch_limit_kw})}
</script>
<template><article class="historical-input"><h3>选择风光荷数据集</h3><p>统一管理年度风光荷数据集；选择数据集后默认预览8760小时，可按需选择连续时段。</p><p v-if="error" class="error">{{error}}</p><div v-if="catalog" class="input-controls"><label>数据集<select v-model="selected" :disabled="disabled||loading"><option v-for="d in catalog.datasets" :key="d.id" :value="d.id" :disabled="!d.available">{{d.name}}{{d.available?'':'（本机缺少文件）'}}</option></select></label><label>起始小时偏移<input v-model.number="start" type="number" min="0" step="1" :disabled="disabled||loading"></label><label>连续小时数<input v-model.number="hours" type="number" min="2" max="8760" step="1" :disabled="disabled||loading"></label><button @click="inspect" :disabled="disabled||loading">{{loading?'正在核验来源…':'预览历史数据'}}</button></div><p class="input-note">网络平衡当前限2—168小时；年度模式请使用对应年度计算入口。单次源荷输入上限8760小时，2024年8784小时应按连续时段选取，不删除闰日。</p><template v-if="preview"><div class="provenance"><strong>{{preview.source_import.name}}</strong><p>{{preview.source_import.first_timestamp}} — {{preview.source_import.last_timestamp}} · {{preview.source_import.hours}} / {{preview.source_import.source_rows}}小时 · kW</p><p v-for="n in preview.source_import.notes" :key="n">{{n}}</p><p v-if="preview.source_import.kind==='extreme'">统一比例系数：{{preview.source_import.scale_factor}}（年度负荷峰值→3715kW）</p><p v-if="preview.source_import.kind==='alashankou'">所选时段质量标记：负荷补值 {{preview.source_import.quality_counts.load_imputed}}小时；供体天气 {{preview.source_import.quality_counts.weather_is_donor_year}}小时。配套51节点骨架，风光在根节点边界注入。</p><details><summary>文件来源与SHA-256</summary><p>{{preview.source_import.file}}</p><code>{{preview.source_import.sha256}}</code></details></div><SeriesPreview :csv="preview.csv"/><div class="input-controls"><button class="primary" :disabled="disabled||loading" @click="apply">应用所选风光荷与配套拓扑</button><button @click="preview=null">取消预览</button></div><p class="input-note">应用会替换当前源荷及拓扑、清空旧阶段与故障引用；历史任务保留。不会自动保存工程或提交计算。阿拉山口沿用物理kW，示例明确使用IEEE33配套网络。</p></template></article></template>
<style scoped>.input-controls{display:flex;align-items:end;gap:12px;flex-wrap:wrap;margin:12px 0}.input-controls label{display:flex;flex-direction:column;gap:6px;font-size:12px;color:#536a86}.input-controls select{max-width:440px;padding:8px}.input-controls input{width:130px;padding:8px}.input-note{font-size:12px;color:#6d7d91}.provenance{padding:12px;background:#f2f6fc;border-left:3px solid #245fd6}.provenance p{font-size:12px;margin:5px 0}.provenance code{overflow-wrap:anywhere}.provenance details p{overflow-wrap:anywhere}</style>
